<template><div class="space-y-7"><div><router-link :to="`/companies/${companyId}`" class="inline-flex items-center gap-1 text-xs font-bold text-[var(--brand-primary)]">← Voltar para empresa</router-link><div class="mt-3 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="premium-kicker">Conta corporativa</p><h1 class="mt-1 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">{{ company?.trade_name||company?.legal_name||'Operação da empresa' }}</h1><p class="mt-1 text-sm text-slate-500">Colaboradores, capacidade contratada e matrículas em um único workspace.</p></div><span v-if="company" class="w-fit rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">{{ company.status||'ACTIVE' }}</span></div></div><div v-if="error" class="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ error }}</div><section class="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-6"><Metric label="Colaboradores" :value="report.total_employees" icon="users"/><Metric label="Matrículas" :value="report.total_enrollments" icon="clipboard"/><Metric label="Ativas" :value="report.active_enrollments" icon="pulse"/><Metric label="Concluídas" :value="report.completed_enrollments" icon="shield"/><Metric label="Certificados" :value="report.certificates" icon="cert"/><Metric label="Conclusão" :value="`${report.completion_rate||0}%`" icon="chart"/></section><section class="grid gap-5 lg:grid-cols-2"><div class="premium-card p-5 sm:p-6"><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><NavIcon name="users"/></span><div><p class="premium-kicker">Onboarding</p><h2 class="mt-1 font-bold text-slate-900">Convidar colaborador</h2></div></div><form class="mt-5 grid gap-3 sm:grid-cols-2" @submit.prevent="invite"><input v-model="inviteForm.full_name" placeholder="Nome completo"/><input v-model="inviteForm.cpf" placeholder="CPF (obrigatório se novo)"/><input v-model="inviteForm.email" type="email" required placeholder="E-mail"/><input v-model="inviteForm.phone" placeholder="Telefone"/><button class="sm:col-span-2 rounded-xl px-4 py-2.5 text-sm font-bold text-white" :style="{background:'var(--brand-primary)'}">Enviar convite</button></form></div><div class="premium-card p-5 sm:p-6"><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-50 text-amber-700"><NavIcon name="calendar"/></span><div><p class="premium-kicker">Capacidade</p><h2 class="mt-1 font-bold text-slate-900">Reservar vagas</h2></div></div><form class="mt-5 grid gap-3" @submit.prevent="saveSeats"><select v-model="seatForm.class_id" required><option value="">Selecione a turma</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.description||item.id }} · {{ item.status }}</option></select><div class="grid gap-3 sm:grid-cols-2"><input v-model.number="seatForm.seats_reserved" required type="number" min="1" placeholder="Vagas reservadas"/><input v-model="seatForm.notes" placeholder="Observação/contrato"/></div><button class="rounded-xl px-4 py-2.5 text-sm font-bold text-white" :style="{background:'var(--brand-primary)'}">Salvar reserva</button></form><div v-if="allocations.length" class="mt-4 space-y-2"><div v-for="a in allocations" :key="a.id" class="rounded-xl bg-slate-50 p-3"><div class="flex justify-between text-xs"><span class="font-semibold text-slate-600">{{ a.seats_used }}/{{ a.seats_reserved }} usadas</span><span class="font-bold text-emerald-700">{{ a.seats_available }} disponíveis</span></div><div class="mt-2 h-1.5 overflow-hidden rounded-full bg-slate-200"><div class="h-full rounded-full" :style="{width:`${Math.min(100,(a.seats_used/a.seats_reserved)*100)}%`,background:'var(--brand-primary)'}"></div></div></div></div></div></section><section class="premium-card overflow-hidden"><div class="flex flex-col gap-4 border-b border-slate-100 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6"><div><p class="premium-kicker">Equipe</p><h2 class="mt-1 font-bold text-slate-900">Colaboradores</h2><p class="mt-1 text-xs text-slate-400">Selecione pessoas e matricule em lote.</p></div><div class="flex flex-col gap-2 sm:flex-row"><select v-model="bulkClass" class="min-w-48"><option value="">Turma para matrícula</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.description||item.id }}</option></select><button :disabled="!bulkClass||!selected.length" @click="bulkEnroll" class="rounded-xl px-4 py-2.5 text-xs font-bold text-white disabled:opacity-40" :style="{background:'var(--brand-primary)'}">Matricular {{ selected.length }}</button></div></div><div v-if="!employees.length" class="p-8 text-center text-sm text-slate-400">Nenhum colaborador vinculado.</div><div v-else class="divide-y divide-slate-100"><div v-for="employee in employees" :key="employee.id" class="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:px-6"><input v-model="selected" type="checkbox" :value="employee.id" class="h-4 w-4 rounded border-slate-300 text-primary-600"/><div class="flex min-w-0 flex-1 items-center gap-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-slate-100 text-xs font-black text-slate-600">{{ initials(employee.full_name) }}</span><div class="min-w-0"><p class="truncate text-sm font-bold text-slate-800">{{ employee.full_name }}</p><p class="truncate text-xs text-slate-400">{{ employee.email }}</p></div></div><span :class="['w-fit rounded-full px-2.5 py-1 text-[10px] font-bold',employee.user_active?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700']">{{ employee.user_active?'Ativo':'Aguardando ativação' }}</span><div class="flex gap-3 text-xs font-bold"><button v-if="!employee.user_active" @click="resend(employee)" class="text-[var(--brand-primary)]">Reenviar ativação</button><button @click="offboard(employee)" class="text-red-600">Desvincular</button></div></div></div></section></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import api from'../api/client';import Metric from'../components/OperationsMetric.vue';import NavIcon from'../components/NavIcon.vue';import{bulkEnrollCompany,getCompanyTrainingReport,inviteCompanyEmployee,listSeatAllocations,offboardCompanyEmployee,resendCompanyActivation,saveSeatAllocation}from'../api/corporate';const route=useRoute(),companyId=route.params.id,company=ref(null),employees=ref([]),classes=ref([]),allocations=ref([]),report=ref({}),error=ref(''),selected=ref([]),bulkClass=ref('');const inviteForm=reactive({full_name:'',cpf:'',email:'',phone:''}),seatForm=reactive({class_id:'',seats_reserved:1,notes:''});const initials=n=>(n||'?').split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();async function load(){try{const[c,e,cl,a,r]=await Promise.all([api.get(`/api/v1/companies/${companyId}`),api.get(`/api/v1/companies/${companyId}/employees`),api.get('/api/v1/classes/'),listSeatAllocations(companyId),getCompanyTrainingReport(companyId)]);company.value=c.data;employees.value=e.data;classes.value=cl.data;allocations.value=a.data;report.value=r.data}catch(e){error.value=e.response?.data?.detail||'Erro ao carregar empresa.'}}async function invite(){try{await inviteCompanyEmployee(companyId,{...inviteForm});Object.assign(inviteForm,{full_name:'',cpf:'',email:'',phone:''});await load()}catch(e){error.value=e.response?.data?.detail||'Não foi possível convidar.'}}async function saveSeats(){try{await saveSeatAllocation(companyId,{...seatForm});await load()}catch(e){error.value=e.response?.data?.detail||'Não foi possível reservar vagas.'}}async function bulkEnroll(){try{await bulkEnrollCompany(companyId,{class_id:bulkClass.value,student_ids:selected.value});selected.value=[];await load()}catch(e){error.value=e.response?.data?.detail||'Não foi possível matricular em lote.'}}async function resend(employee){try{await resendCompanyActivation(companyId,employee.id)}catch(e){error.value=e.response?.data?.detail||'Falha ao reenviar ativação.'}}async function offboard(employee){try{await offboardCompanyEmployee(companyId,employee.id,{deactivate_account:false,cancel_active_corporate_enrollments:true});await load()}catch(e){error.value=e.response?.data?.detail||'Falha ao desvincular colaborador.'}}onMounted(load)</script>
